import{_ as t,H as i,f as E,i as a}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"23 | 图：如何用图表达错综复杂的数据？","description":"","frontmatter":{},"headers":[{"level":2,"title":"关于图，有哪些必备的基本概念和术语？","slug":"关于图-有哪些必备的基本概念和术语","link":"#关于图-有哪些必备的基本概念和术语","children":[{"level":3,"title":"顶点、边、阶","slug":"顶点、边、阶","link":"#顶点、边、阶","children":[]},{"level":3,"title":"无向图、有向图、简单图、多重图、完全图","slug":"无向图、有向图、简单图、多重图、完全图","link":"#无向图、有向图、简单图、多重图、完全图","children":[]},{"level":3,"title":"顶点的度、入度、出度","slug":"顶点的度、入度、出度","link":"#顶点的度、入度、出度","children":[]},{"level":3,"title":"顶点之间的关系、路径、边","slug":"顶点之间的关系、路径、边","link":"#顶点之间的关系、路径、边","children":[]}]},{"level":2,"title":"v","slug":"v","link":"#v","children":[]},{"level":2,"title":"v","slug":"v-1","link":"#v-1","children":[]},{"level":2,"title":"v","slug":"v-2","link":"#v-2","children":[]},{"level":2,"title":"v","slug":"v-3","link":"#v-3","children":[]},{"level":2,"title":"v","slug":"v-4","link":"#v-4","children":[]},{"level":2,"title":"v","slug":"v-5","link":"#v-5","children":[]},{"level":2,"title":"v","slug":"v-6","link":"#v-6","children":[]},{"level":2,"title":"v","slug":"v-7","link":"#v-7","children":[]},{"level":2,"title":"v","slug":"v-8","link":"#v-8","children":[]},{"level":2,"title":"v","slug":"v-9","link":"#v-9","children":[]},{"level":2,"title":"v","slug":"v-10","link":"#v-10","children":[]},{"level":2,"title":"v","slug":"v-11","link":"#v-11","children":[]},{"level":2,"title":"v","slug":"v-12","link":"#v-12","children":[]},{"level":2,"title":"v","slug":"v-13","link":"#v-13","children":[]},{"level":2,"title":"v","slug":"v-14","link":"#v-14","children":[]},{"level":2,"title":"v","slug":"v-15","link":"#v-15","children":[]},{"level":2,"title":"v","slug":"v-16","link":"#v-16","children":[]},{"level":2,"title":"v","slug":"v-17","link":"#v-17","children":[{"level":3,"title":"连通图、子图","slug":"连通图、子图","link":"#连通图、子图","children":[]},{"level":3,"title":"生成树、生成森林","slug":"生成树、生成森林","link":"#生成树、生成森林","children":[]},{"level":3,"title":"树、有向树","slug":"树、有向树","link":"#树、有向树","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后思考","slug":"课后思考","link":"#课后思考","children":[]}],"relativePath":"快速上手C++数据结构与算法/23｜图：如何用图表达错综复杂的数据？.md","filePath":"快速上手C++数据结构与算法/23｜图：如何用图表达错综复杂的数据？.md","lastUpdated":1795557152000}'),l={name:"快速上手C++数据结构与算法/23｜图：如何用图表达错综复杂的数据？.md"};function n(B,e,s,r,h,o){return i(),E("div",null,[...e[0]||(e[0]=[a('<h1 id="_23-图-如何用图表达错综复杂的数据" tabindex="-1">23 | 图：如何用图表达错综复杂的数据？ <a class="header-anchor" href="#_23-图-如何用图表达错综复杂的数据" aria-label="Permalink to &quot;23 | 图：如何用图表达错综复杂的数据？&quot;">​</a></h1><p>你好，我是王健伟。</p><p>经过了长期努力，我们一起学习了树相关的知识。树是整个课程中占据篇幅最大的话题，也是面试和使用中的热门话题。而这一次，我们来说一说图。</p><p>图这种数据结构比树更加复杂。我们回想一下，树形结构中的节点或者说数据之间有明显的层次关系，一个父节点可以有多个子节点，当然，一个子节点只能有唯一的父节点。但在图形结构中，节点之间可以有任意的关系，即任意两个数据都可能相关。</p><h2 id="关于图-有哪些必备的基本概念和术语" tabindex="-1">关于图，有哪些必备的基本概念和术语？ <a class="header-anchor" href="#关于图-有哪些必备的基本概念和术语" aria-label="Permalink to &quot;关于图，有哪些必备的基本概念和术语？&quot;">​</a></h2><p>图涉及的概念和术语比较多，请你投入一定的耐心学习。不过，这些概念和术语不用强记，只需要有印象，后面使用到这些术语的时候再到这节课看看就可以，反复几次，这些概念和术语自然也就记住了。</p><h3 id="顶点、边、阶" tabindex="-1">顶点、边、阶 <a class="header-anchor" href="#顶点、边、阶" aria-label="Permalink to &quot;顶点、边、阶&quot;">​</a></h3><p>先看一些基本概念。在图中，数据元素被称为顶点，和在树中将数据元素称为节点是有区别的，用 v（Vertex）表示。不同的顶点之间的连线称为边，用 e（Edge）表示。</p><p>图（Graph）是由顶点的有穷非空集合和顶点之间的连线（边）的集合组成。通常表示为 G=(V,E)，其中 G 表示一个图，V(G) 代表图 G 中的顶点集合，E(G) 代表图 G 中的边集合。</p><p>用|V|表示图 G 中顶点个数，也称为图 G 的阶。</p><p>用|E|表示图 G 中边的条数。</p><p>图 1 所示就是一个图，其中 A、B、C、D、E、F 是顶点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/1.png" alt=""></a></p><ul><li>图1 图</li></ul><p>注意了，图不可以为空，换句话说，顶点集合 V 不可以为空集。而边集合 E 可以为空，所以，图 2 也是一个图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/2.png" alt=""></a></p><ul><li>图2 包含6个顶点但不包含边的图</li></ul><h3 id="无向图、有向图、简单图、多重图、完全图" tabindex="-1">无向图、有向图、简单图、多重图、完全图 <a class="header-anchor" href="#无向图、有向图、简单图、多重图、完全图" aria-label="Permalink to &quot;无向图、有向图、简单图、多重图、完全图&quot;">​</a></h3><p>如果你刚才观察得仔细，一定会发现上面介绍的图中的边是没有方向的，这种边就叫做无向边（简称边）。如果图中任意两个顶点之间的边都是无向边，则称该图为无向图，比如图 1 就是无向图。</p><p>当然，从一个顶点到另外一个顶点的边也可以是有方向的，这种边称为有向边，也称为弧。如果图中任意两个顶点之间的边都是有向边，则称该图为有向图。图 3 就是一个有向图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/3.png" alt=""></a></p><ul><li>图3 有向图</li></ul><p>对于无向图，只要两个顶点之间有一条边，则这两个顶点之间可以互相到达。图 1 中，连接顶点 A 与 B 之间的边因为不存在方向问题，因此可以表示为无序对 (A,B) 或者 (B,A)，注意这里用的是圆括号表示无向边。</p><p>有向图不同。在图 3 中，顶点 A 到 B 之间存在一条有向边（从 A 指向 B 的箭头），这表示从顶点 A 可以到达顶点 B，但因为顶点 B 到顶点 A 之间并不存在有向边，所以从顶点 B 不可以到达顶点 A。</p><p>这里你可以设想一下微博用户之间的关系。你关注喜欢的账号之后，可以看到对方发的消息，但这并不等于人家也关注了你，如果对方没有关注你，那也看不到你发的消息。</p><p>顶点 A 到顶点 B 的有向边（箭头）就是弧。箭头开始的顶点 A 叫弧尾，箭头指向的顶点 B 叫弧头。这条弧可以用 &lt;​A,B&gt; 表示，注意这里用的是尖括号表示有向边。另外还需要注意方向，不可以写成 &lt;​B,A&gt;。</p><p>图中若不存在顶点到其自身的边，并且同一条边不会重复出现，这种图称为简单图。简单图分为简单无向图（如图 1）和简单有向图（如图 3）。</p><p>图中某两个顶点之间的边数多于一条，或者顶点通过一条边和自己关联，这种图称为多重图。多重图分为多重无向图和多重有向图，如图 4 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/4.png" alt=""></a></p><ul><li>图4 多重图</li></ul><p>数据结构中所讨论的图都是简单图，多重图不在讨论之中。基本上，绝大部分问题通过简单图都可以得到解决，比如微信中不需要自己加自己为好友，也不需要加同一个人多次好友。</p><p>在无向图中，如果任意两个顶点之间都存在边，则称该图为无向完全图。如图 5 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/5.png" alt=""></a></p><ul><li><p>图5 无向完全图</p></li><li><p>n(n−1)</p></li></ul><p>仔细观察后会发现，含有 n 个顶点的无向完全图有</p><ul><li>条边。比如图 5，一共有 5 个顶点，2​</li></ul><p>每个顶点有 4 条边，所以一共有 20 条边，但因为边是两两重复的，比如顶点 A 与顶点 B 的边也是顶点 B 与顶点 A 的边，所以边数要除以 2 也就是 20/2=10 条边。</p><p>在有向图中，如果任意两个顶点之间都存在方向相反的两条弧，则称该图为有向完全图。如图6 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/6.png" alt=""></a></p><ul><li>图6 有向完全图</li></ul><p>从图 6 中不难看到，含有 5 个顶点的有向完全图含有 20 条边，因此，含有 n 个顶点的有向完全图有 n(n-1) 条边。</p><p>有很少条边或者弧的图称为稀疏图，反之称为稠密图。这里稀疏和稠密都是相对而言的，并不是一个精确的数值。</p><h3 id="顶点的度、入度、出度" tabindex="-1">顶点的度、入度、出度 <a class="header-anchor" href="#顶点的度、入度、出度" aria-label="Permalink to &quot;顶点的度、入度、出度&quot;">​</a></h3><p>针对边的讨论结束之后，我们看看和顶点相关的一些概念。</p><p>在无向图中，顶点 v 的度（Degree）是和 v 相关联的边的数目，记为 TD(v)。</p><p>比如图 1 中，顶点 A 的度为 3。深入思考一下，无向图中，因为一条边可以给与这条边相连接的两个顶点分别提供 1 度，所以，无向图中所有顶点的度之和就应该是边数 *2，即 2|E|。</p><p>在有向图中，以顶点 v 为终点（箭头指向 v）的有向边的数目称为顶点 v 的入度（InDegree），记为 ID(v)。以顶点 v 为起点的有向边的数目称为顶点 v 的出度（OutDegree），记为 OD(v)。所以，有向图中顶点 v 的度等于其入度和出度之和，既TD(v)=ID(v)+OD(v)。</p><p>比如图 3 中，顶点 A 的入度为 1，出度为 3，所以顶点 A 的度为 4。有向图中，因为一条边可以给与这条边相连接的两个顶点分别提供 1 出度和 1 入度，所以有向图所有顶点的入度之和与出度之和相等并且等于弧的数量。</p><h3 id="顶点之间的关系、路径、边" tabindex="-1">顶点之间的关系、路径、边 <a class="header-anchor" href="#顶点之间的关系、路径、边" aria-label="Permalink to &quot;顶点之间的关系、路径、边&quot;">​</a></h3><p>现在，我们可以把顶点和边联系起来了。</p><h2 id="v" tabindex="-1">v <a class="header-anchor" href="#v" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-1" tabindex="-1">v <a class="header-anchor" href="#v-1" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-2" tabindex="-1">v <a class="header-anchor" href="#v-2" aria-label="Permalink to &quot;v&quot;">​</a></h2><ul><li>m v​1 v​2 v</li></ul><h2 id="v-3" tabindex="-1">v <a class="header-anchor" href="#v-3" aria-label="Permalink to &quot;v&quot;">​</a></h2><p>顶点</p><ul><li>和顶点的路径是一个顶点序列,,,,……，该序列中的顶点属于图中的​3m​n​n​​</li></ul><p>顶点集合。两个顶点的路径并不唯一，图 7 展示了无向图中从顶点 B 到 D 四种不同的路径，如粗线条所示（当然还有更多）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/7.png" alt=""></a></p><ul><li>图7 无向图从顶点B到顶点D的四种不同路径</li></ul><p>这里注意，对于有向图，路径也是有向的，图 8 展示了有向图中从顶点 A 到顶点 D 的两种不同路径。而对于 B 到 A 之间就不存在路径。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/8.png" alt=""></a></p><ul><li>图8 有向图从顶点A到顶点D的两种不同路径</li></ul><p>我们把第一个顶点和最后一个顶点相同的路径称为回路或环。如图 9 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/9.png" alt=""></a></p><ul><li>图9 有向图和无向图中的环</li></ul><p>这么多的路径，其实也是涉及了一些专有名词的，我把它列在这里，你可以参考。</p><p>简单路径：在路径序列中顶点不重复出现的路径称为简单路径。图 7 中，从顶点 A 到顶点 D可以有多种不同路径，比如 A、B、A、D 这个路径，因为顶点 A 重复出现了，所以这就不是一个简单路径。</p><p>简单回路 / 简单环：除第一个顶点和最后一个顶点，其余顶点不重复出现的回路叫简单回路或简单环。</p><p>路径长度：路径上的边或弧的数目。图 7 中的四幅图路径长度分别为 1、2、2、3，图 8 中的两幅图路径长度分别为 3、1。</p><h2 id="v-4" tabindex="-1">v <a class="header-anchor" href="#v-4" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-5" tabindex="-1">v <a class="header-anchor" href="#v-5" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-6" tabindex="-1">v <a class="header-anchor" href="#v-6" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-7" tabindex="-1">v <a class="header-anchor" href="#v-7" aria-label="Permalink to &quot;v&quot;">​</a></h2><p>点到点的距离：从顶点</p><ul><li>到的最短路径如果存在，则此路径的长度称为从顶点到m​nm​n​​</li></ul><h2 id="v-8" tabindex="-1">v <a class="header-anchor" href="#v-8" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-9" tabindex="-1">v <a class="header-anchor" href="#v-9" aria-label="Permalink to &quot;v&quot;">​</a></h2><p>的距离，如果</p><ul><li>到之间不存在路径，则称他们之间的距离为无穷（∞）。m​n​</li></ul><h2 id="v-10" tabindex="-1">v <a class="header-anchor" href="#v-10" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-11" tabindex="-1">v <a class="header-anchor" href="#v-11" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-12" tabindex="-1">v <a class="header-anchor" href="#v-12" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-13" tabindex="-1">v <a class="header-anchor" href="#v-13" aria-label="Permalink to &quot;v&quot;">​</a></h2><p>无向图中，若从顶点</p><ul><li>到之间有路径存在，则称和是连通的。图 10 中，顶点 Fm​nm​n​​</li></ul><p>与其他顶点之间不连通，而除 F 外的其他顶点是彼此连通的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/10.png" alt=""></a></p><ul><li>图10 无向图中顶点连通与不连通展示</li></ul><h2 id="v-14" tabindex="-1">v <a class="header-anchor" href="#v-14" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-15" tabindex="-1">v <a class="header-anchor" href="#v-15" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-16" tabindex="-1">v <a class="header-anchor" href="#v-16" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="v-17" tabindex="-1">v <a class="header-anchor" href="#v-17" aria-label="Permalink to &quot;v&quot;">​</a></h2><p>有向图中，若从顶点</p><ul><li>到之间和从顶点到之间都有路径，则称这两个顶点是强m​n​nm​​</li></ul><p>连通的。图 3 中，顶点 A 和 D 之间就是强连通的，而顶点 A 和 B 之间就不是强连通的，因为从 B 到 A 不存在路径。</p><p>有些图的边或弧有与其相关的数字，这种与图的边或者弧相关的数字叫权（Weight）或者权值。这些权值可以表示从一个顶点到另一个顶点的距离、时间、票价等数据。这种带权的图通常称为带权图或网。如图 11 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/11.png" alt=""></a></p><ul><li>图11 网</li></ul><h3 id="连通图、子图" tabindex="-1">连通图、子图 <a class="header-anchor" href="#连通图、子图" aria-label="Permalink to &quot;连通图、子图&quot;">​</a></h3><p>局部的顶点、边了解完之后，我们再将视角放大，着眼于整张图。</p><p>如果无向图中任意两个顶点都是连通的，则称图为连通图，否则称为非连通图。比如前面的图1 就是一个连通图。不难想象得出这么几个结论。</p><ul><li><p>对于具有 n 个顶点的无向图，如果是连通图，则最少要有 n-1 条边。简单绘制一个有 3 个顶点的无向图，你就能得到结论。(n−1)(n−2)对于具有 n 个顶点的无向图，如果是非连通图，则最多只能有条边。2​</p></li><li><p>n(n−1)</p></li></ul><p>如何推出这个结论呢？试想，含有 n 个顶点的无向完全图有</p><ul><li>条边，比如含有 5 个顶点2​</li></ul><p>的无向完全图有 10 条边，那么如果再增加进来一个顶点变成 6 个顶点，现在只要将这个新增加的顶点和任意其他顶点连线，就构成了连通图，所以 6 个顶点的非连通图最多只能有 10 条边。</p><p>而如果有向图中任意一对顶点都是强连通的呢？那我们称此图为强连通图，如图 12 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/12.png" alt=""></a></p><ul><li>图12 强连通图</li></ul><p>不难想象，对于有 n 个顶点的有向图，若是强连通图，则最少要有 n 条边以构成回路，如图13 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/13.png" alt=""></a></p><ul><li>图13 含有5个顶点的有向图最少要有5条边才构成强连通图</li></ul><p>我们假设有图一和图二两个图，如果图二的顶点是图一的顶点的子集，并且图二的边是图一边的子集，则称图二是图一的子图。如果子图包含原图的所有顶点，则称该子图为原图的一个生成子图，图 14 从第 2 个图开始的图都是第 1 个图的子图，而最后一个子图是原图的生成子图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/14.png" alt=""></a></p><ul><li>图14 无向图和有向图的子图</li></ul><p>连通分量：无向图中的极大连通子图称为连通分量。换句话说，极大连通子图必须连通并且包含尽可能多的顶点和边，如图 15 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/15.png" alt=""></a></p><ul><li>图15 无向图和无向图的4个连通分量</li></ul><p>举个例子，全国各个城市的地铁网，比如上海地铁网是全国地铁网的连通分量，深圳地铁网是全国地铁网的连通分量，诸如此类。</p><p>强连通分量：有向图中的极大强连通子图称为强连通分量。这里的强连通意味着两两可达。如图 16 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/16.png" alt=""></a></p><ul><li>图16 有向图和有向图的3个强连通分量</li></ul><h3 id="生成树、生成森林" tabindex="-1">生成树、生成森林 <a class="header-anchor" href="#生成树、生成森林" aria-label="Permalink to &quot;生成树、生成森林&quot;">​</a></h3><p>一个无向的连通图的生成树是包含图中全部顶点的一个极小的连通子图。这里的极小指边尽可能要少，如图 17 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/17.png" alt=""></a></p><ul><li>图17 无向连通图和无向连通图的3个生成树</li></ul><p>从图 17 可以看到，无向连通图的生成树可以有多个，生成树中如果有 n 个顶点，则必须有 n-1 条边。因为我们前面讲解过，n 个顶点的无向图，如果是连通图，则最少要有 n-1 条边。话说回来，如果一个无向图有 n 个顶点和小于 n-1 条边，则肯定是非连通图。如果它多于 n-1条边，则一定有回路（环）。但有 n-1 条边的图不一定是生成树，因为生成树要求连通。</p><p>你可以想象一下通往各个城市的道路铺设场景，其中就可以用到生成树。生成树既可以保证各个城市之间彼此都可以到达，又可以保证铺设的道路尽可能少，而后可以在多个生成树中挑选最优的生成树方案。比如如果想最节省成本，就可以把修每段路（边）的价格作为权值来计算总成本并最终挑选出总成本最少的修路方案如图 18 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/18.png" alt=""></a></p><ul><li>图18 带权值的无向连通图</li></ul><p>当图是带权图时，一条路径上所有边的权值之和称为带权路径长度。</p><p>在无向非连通图中，连通分量的生成树构成了无向非连通图的生成森林。参照图 15 绘制图19：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/19.png" alt=""></a></p><ul><li>图19 无向非连通图的生成森林</li></ul><h3 id="树、有向树" tabindex="-1">树、有向树 <a class="header-anchor" href="#树、有向树" aria-label="Permalink to &quot;树、有向树&quot;">​</a></h3><p>最后需要注意的是，在无向图中，树是连通且不存在回路的，如图 20 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/20.png" alt=""></a></p><ul><li>图20 被称为树的无向图</li></ul><p>从图 20 可以看到，以 E、A 为根向下绘制看起来更像一棵树，当然，以任何其他顶点为根都是可以的。请注意，具有 n 个顶点的树，必然会有 n-1 条边，否则一定会是有回路的。</p><p>而在有向图中，一个顶点的入度为 0，其余顶点的入度均为 1，称为有向树，如图 21 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/21.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/21.png" alt=""></a></p><ul><li>图21 被称为有向树的有向图</li></ul><p>图 21 就是有向树，其中入度为 0 的顶点可以当做树的根，所以顶点 E 作为根。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课我们讲解的关于图的概念不少，不必死记硬背，主要是为了我们后续学习的时候，你有一个随时可回顾的依据。我把今天的内容分成了几个主题，把主题以及主题中一些比较重要的文字列举出来作为线索，供你重点理解和记忆。</p><p>主题一：顶点、边、阶</p><p>主题二：无向图、有向图、简单图、多重图、完全图</p><ul><li>n(n−1)含有 n 个顶点的无向完全图有条边。2​含有 n 个顶点的有向完全图有 n(n-1) 条边。</li></ul><p>主题三：顶点的度、入度、出度</p><ul><li><p>无向图中所有顶点的度之和是边数 *2，即 2|E|。</p></li><li><p>有向图所有顶点的入度之和与出度之和相等并且等于弧的数量。</p></li></ul><p>主题四：顶点之间的关系、路径、边</p><p>主题五：连通图、子图</p><ul><li>对于具有 n 个顶点的无向图，如果是连通图，则最少要有 n-1 条边。(n−1)(n−2)对于具有 n 个顶点的无向图，如果是非连通图，则最多只能有条边。2​对于有 n 个顶点的有向图，若是强连通图，则最少要有 n 条边以构成回路。</li></ul><p>主题六：生成树、生成森林</p><ul><li>如果一个无向图有 n 个顶点和小于 n-1 条边，则肯定是非连通图。如果它多于 n-1 条边，则一定有回路（环）。</li></ul><p>主题七：树、有向树</p><p>此外，我把图中涉及的概念整理成图 22 方便你复习。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/22.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/23.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/23/23.png" alt=""></a></p><ul><li>图22 图的基本概念、术语和需要有印象的内容整理总结</li></ul><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">​</a></h2><p>你能想到的图的应用有哪些呢？</p><p>欢迎你在留言区分享自己的思考。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习进步。我们下一讲见！</p>',163)])])}const g=t(l,[["render",n]]);export{u as __pageData,g as default};
